"""Aggregate only observed receipts; missing evidence stays NOT_RUN."""
import json,csv,statistics,hashlib
from pathlib import Path
R=Path('/workspace/Self-Audit/reports/automatic_pilot_pro4000');ROOT=R.parents[1];rows=[];patients=[];failures=[]
for regime in [p.stem.removeprefix('results_') for p in sorted(R.glob('results_equal*.json'))]:
 p=R/f'results_{regime}.json'
 if not p.exists():continue
 for item in json.loads(p.read_text()):
  a=item['arm'];m=item['metrics'];t=item['training_report'];row={'comparison':regime,'arm':a,'steps':t['steps'],'foreground_Dice':m['foreground_patient_macro'],'RV_Dice':m['macro_patient']['RV']['dice'],'MYO_Dice':m['macro_patient']['MYO']['dice'],'LV_Dice':m['macro_patient']['LV']['dice'],'patients':m['total_patients_scored'],'phase_seconds':t['phase_cost_seconds'],'export_seconds':m['cold_output_total_seconds'],'VRAM_allocated_MiB':t['peak_vram_allocated_mb'],'VRAM_reserved_MiB':t['peak_vram_reserved_mb'],'updates_per_second':t['throughput_updates_per_sec'],'acceptance':t['acceptance_rate'],'nonzero_extra_updates':t['nonzero_displacement_updates'],'checkpoint_sha256':t['final_manifest_sha256']};rows.append(row)
  for pid,pv in m['patients'].items():
   values=[pv[c] for c in ['RV','MYO','LV'] if pv[c] is not None];v=statistics.mean(values) if values else None;pr={'comparison':regime,'arm':a,'patient':pid,'RV':pv['RV'],'MYO':pv['MYO'],'LV':pv['LV'],'foreground':v};patients.append(pr)
   if v is not None and v<.2:failures.append(pr)
for name,rs in [('COMPARISON.csv',rows),('PATIENT_METRICS.csv',patients),('FAILURE_PATIENTS.csv',failures)]:
 if rs:
  with (R/name).open('w') as f:w=csv.DictWriter(f,fieldnames=list(rs[0]));w.writeheader();w.writerows(rs)
lines=['# Real-patient PRO4000 execution','', 'Base commit: `93f7c7a1f9606a68955f849dd580b90462ad329e`; executable patch: `SOURCE_PATCH_B128_FINAL.patch`.','', 'ACDC: TRAIN80 (L8/U72), VAL18, TEST50; locked split unchanged; excluded055/076. M&Ms is separate (original TRAIN175/VAL34/TEST136; after image-duplicate quarantine, active TRAIN170/VAL32/TEST135). No M&Ms training or pooling.','', 'Batch 128 across all arms; full_ema accumulates one effective batch across microbatches of 40 and takes one optimizer/EMA step. All metrics below are measured raw-student native predictions, frozen before reference scoring.','', '| Comparison | Arm | Steps | RV | MYO | LV | FG mean | Phase s | Export s | Peak reserved MiB |','|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for r in rows:lines.append('| '+' | '.join(str(r[k]) for k in ['comparison','arm','steps','RV_Dice','MYO_Dice','LV_Dice','foreground_Dice','phase_seconds','export_seconds','VRAM_reserved_MiB'])+' |')
for regime in [p.stem.removeprefix('results_') for p in sorted(R.glob('results_equal*.json'))]:
 p=R/f'decision_{regime}.json';lines+=['',f'## Decision: {regime}','',json.dumps(json.loads(p.read_text())['decision_gate'],indent=2) if p.exists() else 'NOT_RUN']
lines+=['','## Limitations','','Single patient-label seed and single run per arm; no statistical or clinical certification. Drive TEST50 was previously exposed in this repository and is not a new confirmatory cohort. Drive label provenance is not independently challenge certified. Equal-update is not equal-compute evidence. Fresh equal-time phase spread must be within 5%; export and common warm costs are reported separately. M&Ms uses the verified VAL32 subset of original VAL34 as a separate cross-dataset generalization cohort; original TEST136 is not scored. Eight exact-voxel duplicate IDs were excluded from derived manifests without changing raw splits/files. Temporal spacing is missing in M&Ms headers; frame-index processing does not invent seconds. DINO weights match the authorized backup and recorded full SHA; independent upstream full-hash certification unavailable. Full-EMA follows the executable base commit and trains encoder/body, despite runbook frozen-encoder wording. AMP is disabled to preserve finite argmax guard semantics. No W&B credentials; structured file logging is active.','','## Locations','','Checkpoints/native compressed predictions: `/workspace/Self-Audit/runs/pro4000/`. Prepared data: `/workspace/Self-Audit/data/prepared/`. Raw data: `data/ACDC/`, `data/MnM/`. All original archives retained in `data/archives/`. Reproduction: `execute_B128.sh`, `run_stage.py`, `evaluate_stage.py`, `PLAN.json`, `SOURCE_PATCH_B128_FINAL.patch`, pinned data/model/checkpoint manifests. No raw patient data or checkpoints are included in Git.']
(R/'REPORT.md').write_text('\n'.join(lines)+'\n')
(R/'ARTIFACT_HASHES.json').write_text(json.dumps({str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(R.iterdir()) if p.is_file() and p.suffix in ('.py','.sh','.json','.patch','.csv','.md') and p.name!='ARTIFACT_HASHES.json'},indent=2)+'\n')
print('REPORT_GENERATED',len(rows),'comparisons',len(patients),'patient rows')
